package io.github.rivomesh.acceptance;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import io.github.rivomesh.*;
import io.github.rivomesh.cdc.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.sql.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Actual release worker + actual selected/acknowledging consumer; independent SQL/MQ failures. */
public final class ClassicPipelineAcceptance {
    final Path directory;final String database;final PipelineConfig config=new PipelineConfig();final Map<String,MessageEvent> received=new LinkedHashMap<>();
    Process worker;Path log;String queue;
    ClassicPipelineAcceptance()throws Exception{directory=Paths.get(System.getenv("RIVOMESH_CLASSIC_RESTART_DIR")).resolve("acceptance");Files.createDirectory(directory);Files.setPosixFilePermissions(directory,PosixFilePermissions.fromString("rwx------"));database="classic_"+UUID.randomUUID().toString().replace("-","").substring(0,20);}
    static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    interface Condition{boolean ready()throws Exception;}
    void await(Condition condition)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);Exception last=null;while(System.nanoTime()<end){if(worker!=null&&!worker.isAlive())throw new AssertionError("Worker exited: "+new String(Files.readAllBytes(log),StandardCharsets.UTF_8));try{if(condition.ready())return;}catch(Exception retry){last=retry;}Thread.sleep(100);}throw new AssertionError("Condition timed out: "+(last==null?"":last.getClass().getName())+"; worker="+new String(Files.readAllBytes(log),StandardCharsets.UTF_8));}
    void sql(String endpoint,String statement)throws Exception{try(Connection c=JdbcConnections.open("com.mysql.cj.jdbc.Driver","jdbc:mysql://"+endpoint+":3306/?useSSL=false&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000","root","Sync@Test123");Statement s=c.createStatement()){s.execute(statement);}}
    Connection postgres()throws Exception{PipelineConfig.Target pg=config.targets.get(1);return JdbcConnections.open("org.postgresql.Driver",pg.url,pg.username,pg.password);}
    void pgSql(String sql)throws Exception{try(Connection c=postgres();Statement s=c.createStatement()){s.execute(sql);}}
    long pgCount(String condition)throws Exception{try(Connection c=postgres();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT count(*) FROM "+Sql.pg(database+"_copy")+".items WHERE "+condition)){r.next();return r.getLong(1);}}
    long last(JdbcJournal journal)throws Exception{return ((Number)journal.status().get("lastSequence")).longValue();}
    long ack(JdbcJournal journal,String id)throws Exception{return journal.subscriptions().stream().filter(s->s.id.equals(id)).findFirst().get().acknowledged;}
    void start()throws Exception{Path file=directory.resolve("task.yml");new ObjectMapper(new YAMLFactory()).writeValue(file.toFile(),config);Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-------"));log=directory.resolve("worker-"+UUID.randomUUID()+".log");worker=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-Xmx256m","-jar",System.getProperty("sync.test.jar"),"run",file.toString()).redirectErrorStream(true).redirectOutput(log.toFile()).start();}
    void kill()throws Exception{if(worker!=null&&worker.isAlive()){worker.destroyForcibly();require(worker.waitFor(10,TimeUnit.SECONDS),"Worker did not stop");}}
    void inspect()throws Exception{Path output=directory.resolve("events-"+UUID.randomUUID()+".json"),errors=directory.resolve("consumer-"+UUID.randomUUID()+".log");Process reader=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-Xmx128m","-cp",System.getProperty("java.class.path"),ClassicInspector.class.getName(),queue,output.toString()).redirectErrorStream(true).redirectOutput(errors.toFile()).start();if(!reader.waitFor(15,TimeUnit.SECONDS)){reader.destroyForcibly();reader.waitFor(5,TimeUnit.SECONDS);throw new IllegalStateException("CLASSIC_INSPECTOR_TIMEOUT");}if(reader.exitValue()!=0)throw new IllegalStateException("CLASSIC_INSPECTOR_FAILED");for(MessageEvent event:Codec.JSON.readValue(Files.readAllBytes(output),MessageEvent[].class)){require("classic".equals(event.subscriptionId),"Foreign subscription event");MessageEvent old=received.putIfAbsent(event.id,event);if(old!=null)require(Codec.encode(old).equals(Codec.encode(event)),"Replay changed immutable payload");}}
    Map<String,List<Cell>> rows(String name){String tableId=TableSchema.identity(database,"",name);Set<String> complete=new HashSet<>(),snapshots=new HashSet<>();for(MessageEvent event:received.values()){if("COMMIT".equals(event.kind))complete.add(event.transactionId);if("SNAPSHOT_END".equals(event.kind))snapshots.add(event.snapshotId);}Map<String,List<Cell>> rows=new LinkedHashMap<>();for(MessageEvent event:received.values()){if(!tableId.equals(event.tableId)||event.change==null)continue;if("SNAPSHOT_ROW".equals(event.kind)&&!snapshots.contains(event.snapshotId)||"ROW".equals(event.kind)&&!complete.contains(event.transactionId))continue;if(!Arrays.asList("ROW","SNAPSHOT_ROW").contains(event.kind))continue;if(event.change.before!=null&&(event.change.after==null||!Objects.equals(event.beforeKey,event.afterKey)))rows.remove(event.beforeKey);if(event.change.after!=null)rows.put(event.afterKey,event.change.after);}return rows;}
    boolean has(String id){return rows("items").values().stream().anyMatch(row->id.equals(row.get(0).value));}
    void marker(String action)throws Exception{Files.write(Paths.get(System.getenv("RIVOMESH_CLASSIC_RESTART_DIR")).resolve(action+".request"),new byte[]{1});await(()->Files.exists(Paths.get(System.getenv("RIVOMESH_CLASSIC_RESTART_DIR")).resolve(action+".done")));}
    void configure(){config.pipelineId=database;config.source.clusterId=database;config.source.host="mysql";config.source.port=3306;config.source.username="root";config.source.password="Sync@Test123";config.source.serverId=991234;config.databases=Collections.singletonList(database);config.chunkSize=1;config.leaseMillis=5000;config.heartbeatMillis=300;config.retryDelayMillis=300;config.pollIntervalMillis=100;config.journal.path=directory.resolve("journal").toString();
        PipelineConfig.Target classic=new PipelineConfig.Target();classic.id="classic";classic.product=TargetProduct.ACTIVEMQ_CLASSIC;classic.url="activemq://classic:61616";classic.username="admin";classic.password="Classic@Test123";classic.mappings.put(database,"events");classic.messaging=new PipelineConfig.Messaging();classic.messaging.stream="rivomesh";classic.messaging.broker="rivomesh-core";classic.messaging.adminUrl="http://classic:8161/api/jolokia/";classic.messaging.connectTimeoutMillis=2000;classic.messaging.requestTimeoutMillis=3000;config.targets.add(classic);
        PipelineConfig.Target pg=new PipelineConfig.Target();pg.id="postgres";pg.product=TargetProduct.POSTGRESQL;pg.url="jdbc:postgresql://postgres:5432/sync_test?connectTimeout=3&socketTimeout=10";pg.username="sync_test";pg.password="Sync@Test123";pg.metadataSchema=database+"_meta";pg.mappings.put(database,database+"_copy");config.targets.add(pg);config.validate();}
    void run()throws Exception{configure();String items=Sql.mysql(database)+".items",duplicates=Sql.mysql(database)+".duplicates";sql("mysql","CREATE DATABASE "+Sql.mysql(database));try{sql("mysql","CREATE TABLE "+items+" (id INT PRIMARY KEY,document JSON,twice INT GENERATED ALWAYS AS(id*2) STORED) ENGINE=InnoDB");sql("mysql","INSERT INTO "+items+" (id,document) VALUES (1,'{\"large\":18446744073709551615}')");sql("mysql","CREATE TABLE "+duplicates+" (label VARCHAR(100)) ENGINE=InnoDB");sql("mysql","INSERT INTO "+duplicates+" VALUES ('same'),('same')");config.prepareLocalDirectory();try(JdbcJournal journal=new JdbcJournal(config.journalSettings())){
            start();await(()->journal.status().get("generation")!=null);queue=io.github.rivomesh.transport.classic.ClassicTransport.physicalQueue("rivomesh",MessagePublishers.binding(database,"classic",(String)journal.status().get("generation")));await(()->{inspect();return received.values().stream().filter(e->e.kind.equals("SNAPSHOT_END")).count()==2;});require(rows("items").size()==1&&rows("duplicates").size()==2,"Snapshot rows/keyless multiplicity mismatch");require(rows("items").values().iterator().next().get(1).value.contains("18446744073709551615"),"JSON precision lost");await(()->pgCount("id=1 AND twice=2")==1);
            sql("mysql","UPDATE "+items+" SET id=2 WHERE id=1");sql("mysql","DELETE FROM "+duplicates+" LIMIT 1");await(()->{inspect();return has("2")&&!has("1")&&rows("duplicates").size()==1;});require(rows("items").values().iterator().next().get(2).value.equals("4"),"Generated value lost");await(()->ack(journal,"classic")==last(journal)&&ack(journal,"postgres")==last(journal));
            marker("stop");sql("mysql","INSERT INTO "+items+" (id,document) VALUES (3,'{}')");await(()->pgCount("id=3")==1);await(()->journal.subscriptions().stream().anyMatch(s->s.id.equals("classic")&&s.state.equals("RUNNING")&&s.errorCode!=null));require(ack(journal,"classic")<last(journal),"Classic checkpoint advanced through outage");marker("start");await(()->{inspect();return has("3")&&ack(journal,"classic")==last(journal);});
            kill();sql("mysql","INSERT INTO "+items+" (id,document) VALUES (4,NULL)");start();await(()->{inspect();return has("4")&&ack(journal,"classic")==last(journal);});require(rows("duplicates").size()==1,"Restart duplicated keyless rows");require(received.values().stream().filter(e->e.kind.equals("SNAPSHOT_END")).count()==2,"Restart created a new snapshot");await(()->pgCount("id=4")==1);
            pgSql("ALTER TABLE "+Sql.pg(database+"_copy")+".items ADD CONSTRAINT block_five CHECK(id<5)");sql("mysql","INSERT INTO "+items+" (id,document) VALUES (5,'{}')");await(()->journal.subscriptions().stream().anyMatch(s->s.id.equals("postgres")&&s.state.equals("PAUSED")));await(()->{inspect();return has("5")&&ack(journal,"classic")==last(journal);});require(pgCount("id=5")==0,"SQL failure was skipped");long error=journal.subscriptions().stream().filter(s->s.id.equals("postgres")).findFirst().get().errorGeneration;pgSql("ALTER TABLE "+Sql.pg(database+"_copy")+".items DROP CONSTRAINT block_five");journal.resume("postgres",error);await(()->pgCount("id=5")==1&&ack(journal,"postgres")==last(journal));
            ClassicAcceptance.operation(queue,"purge()");sql("mysql","INSERT INTO "+items+" (id,document) VALUES (6,'{}')");await(()->journal.subscriptions().stream().anyMatch(s->s.id.equals("classic")&&s.state.equals("PAUSED")));await(()->pgCount("id=6")==1&&ack(journal,"postgres")==last(journal));require(ack(journal,"classic")<last(journal),"Purged queue reused old checkpoint");require(ClassicAcceptance.admin().count(queue)==0,"Purged initialized queue silently reseeded");@SuppressWarnings("unchecked")Map<String,String> fences=(Map<String,String>)PipelineControls.pause(config).get("targetFences");require("FENCED".equals(fences.get("postgres"))&&"UNCONFIRMED_IN_FLIGHT_PUBLICATION".equals(fences.get("classic")),"Wrong pause fencing guarantee");
        }System.out.println("CLASSIC_PIPELINE_ACCEPTED: release Java 21, actual MySQL8.4 snapshot/CDC/keyless/JSON/generated values, selected consumer durable ACK, broker outage independent SQL, worker SIGKILL/resume, SQL constraint failure/retry independent MQ, purge protection and explicit pause fencing");}finally{kill();sql("mysql","DROP DATABASE IF EXISTS "+Sql.mysql(database));}}
    public static void main(String[] args)throws Exception{new ClassicPipelineAcceptance().run();}
}
